// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.util.concurrent.TimeUnit;

import org.eclipse.rdf4j.sail.lmdb.frontier.FrontierFallbackReason;
import org.eclipse.rdf4j.sail.lmdb.frontier.FrontierStatisticsException;
import org.junit.jupiter.api.Test;

class FrontierRebuildSchedulePolicyTest {

	private static final long QUIET = TimeUnit.SECONDS.toNanos(1L);
	private static final long DEADLINE = TimeUnit.SECONDS.toNanos(5L);
	private static final long T0 = 1_000_000_000_000L;

	@Test
	void withinQuietPeriodAndUnderDeadlineDefers() {
		long now = T0 + TimeUnit.MILLISECONDS.toNanos(2_500L);
		long lastRequest = now - TimeUnit.MILLISECONDS.toNanos(300L);
		assertFalse(FrontierRebuildSchedulePolicy.shouldStartBaseRebuild(now, lastRequest, true, T0, QUIET,
				DEADLINE));
	}

	@Test
	void quietPeriodElapsedStartsEvenWithoutPendingRebuild() {
		long now = T0 + TimeUnit.MILLISECONDS.toNanos(1_500L);
		assertTrue(FrontierRebuildSchedulePolicy.shouldStartBaseRebuild(now, T0, false, 0L, QUIET, DEADLINE));
	}

	@Test
	void deadlineExceededStartsWhileRequestsKeepArriving() {
		long now = T0 + DEADLINE;
		long lastRequest = now - TimeUnit.MILLISECONDS.toNanos(100L);
		assertTrue(FrontierRebuildSchedulePolicy.shouldStartBaseRebuild(now, lastRequest, true, T0, QUIET,
				DEADLINE));
	}

	@Test
	void withoutPendingRebuildOnlyTheQuietPeriodApplies() {
		long now = T0 + 2L * DEADLINE;
		long lastRequest = now - TimeUnit.MILLISECONDS.toNanos(100L);
		assertFalse(FrontierRebuildSchedulePolicy.shouldStartBaseRebuild(now, lastRequest, false, T0, QUIET,
				DEADLINE));
	}

	@Test
	void nanoTimeWrapAroundIsHandledByDifferences() {
		long now = Long.MIN_VALUE + TimeUnit.MILLISECONDS.toNanos(200L);
		long lastRequest = now - TimeUnit.MILLISECONDS.toNanos(100L);
		long pendingSince = Long.MAX_VALUE - DEADLINE + TimeUnit.MILLISECONDS.toNanos(50L);
		assertTrue(FrontierRebuildSchedulePolicy.shouldStartBaseRebuild(now, lastRequest, true, pendingSince,
				QUIET, DEADLINE));
	}

	@Test
	void permanentFailureEscalatesImmediately() {
		FrontierStatisticsException permanent = FrontierStatisticsException.permanent(
				FrontierFallbackReason.MEMORY_PRESSURE, "Frontier signed-delta publication exceeds its envelope");
		assertTrue(FrontierRebuildSchedulePolicy.deltaFailureRequiresBaseRebuild(permanent, 1, 8));
	}

	@Test
	void confidenceTooWideEscalatesImmediately() {
		FrontierStatisticsException layerLimit = FrontierStatisticsException.transientFailure(
				FrontierFallbackReason.CONFIDENCE_TOO_WIDE, "Frontier signed-delta layer limit");
		assertTrue(FrontierRebuildSchedulePolicy.deltaFailureRequiresBaseRebuild(layerLimit, 1, 8));
	}

	@Test
	void transientFailuresRetryUntilTheBound() {
		IOException journal = new IOException("journal temporarily unavailable");
		FrontierStatisticsException governor = FrontierStatisticsException.transientFailure(
				FrontierFallbackReason.MEMORY_PRESSURE, "heap governor refused the workspace");
		for (int attempt = 1; attempt < 8; attempt++) {
			assertFalse(FrontierRebuildSchedulePolicy.deltaFailureRequiresBaseRebuild(journal, attempt, 8),
					"attempt " + attempt);
			assertFalse(FrontierRebuildSchedulePolicy.deltaFailureRequiresBaseRebuild(governor, attempt, 8),
					"attempt " + attempt);
		}
		assertTrue(FrontierRebuildSchedulePolicy.deltaFailureRequiresBaseRebuild(journal, 8, 8));
		assertTrue(FrontierRebuildSchedulePolicy.deltaFailureRequiresBaseRebuild(governor, 8, 8));
	}
}
